/* From Uiverse.io by 1osm - Tags: card */
.__UIV_SCOPE__ .card {
  width: 250px;
  height: 90px;
  background: #262626;
}

.__UIV_SCOPE__ .smallIcon {
  width: 100%;
  height: 100%;
  background-color: #ff5858;
}

.__UIV_SCOPE__ .smallIcon div {
  background: linear-gradient(120deg, #e5e5e5 30%, #f0f0f0 38%, #f0f0f0 
  40%, #e5e5e5 48%);
  margin-top: 10px;
  background-size: 200% 100%;
  background-position: 100% 0;
  animation: load89234 2s infinite;
  color: #262626;
  font-weight: bold;
  font-size: 15px;
}

.__UIV_SCOPE__ .Icon {
  margin: 10px;
  width: 70px;
  height: 70px;
  float: left;
  border-radius: 5px;
}

.__UIV_SCOPE__ .Name {
  width: 90px;
  height: 20px;
  float: left;
  transform: translate(10px ,0px);
  border-radius: 5px;
}

.__UIV_SCOPE__ .Roles {
  width: 40px;
  height: 20px;
  float: left;
  transform: translate(20px ,0px);
  border-radius: 5px;
}

.__UIV_SCOPE__ .Descripion {
  margin: 10px;
  width: 140px;
  height: 45px;
  float: left;
  transform: translate(0px ,-5px);
  border-radius: 5px;
}

@keyframes load89234 {
  100% {
    background-position: -100% 0;
  }
}
